import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  /** Clerk's user id, once this person has signed in at least once. */
  clerkId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

/**
 * Finds the local user record for a signed-in Clerk identity, creating one on
 * first sign-in. Matches by Clerk id first, then falls back to email so a
 * seeded user (e.g. "ada@example.com" above) is claimed instead of duplicated
 * once that person actually signs up through Clerk.
 */
function getOrCreateUserForClerkIdentity(clerkId: string, email: string, name: string): User {
  let user = users.find((u) => u.clerkId === clerkId);
  if (user) return user;

  user = users.find((u) => u.email === email);
  if (user) {
    user.clerkId = clerkId;
    return user;
  }

  user = {
    id: clerkId,
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    clerkId,
  };
  users.push(user);
  return user;
}

/** Returns the locally-tracked user for the current Clerk session, if any. */
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;

  const email = clerkUser.primaryEmailAddress?.emailAddress ?? clerkUser.emailAddresses[0]?.emailAddress ?? "";
  const name =
    [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
    clerkUser.username ||
    email ||
    "Unnamed";

  return getOrCreateUserForClerkIdentity(clerkUser.id, email, name);
}

